def last(iterable, default=_marker):
    """Return the last item of *iterable*, or *default* if *iterable* is
    empty.

        >>> last([0, 1, 2, 3])
        3
        >>> last([], 'some default')
        'some default'

    If *default* is not provided and there are no items in the iterable,
    raise ``ValueError``.
    """
    try:
        if getattr(iterable, '__reversed__', None):
            return next(reversed(iterable))
        return deque(iterable, maxlen=1)[-1]
    except (IndexError, StopIteration):
        if default is _marker:
            raise ValueError(
                'last() was called on an empty iterable, '
                'and no default value was provided.'
            )
        return default

def peek(self, default=_marker):
    try:
        peeked = next(self)
    except StopIteration:
        if default is _marker:
            raise
        return default
    # maxlen=0 cannot store the item we just consumed, so put it back.
    if getattr(self._cache, 'maxlen', None) == 0:
        self._source = chain((peeked,), self._source)
        self._index = None
        return peeked
    if self._index is None:
        self._index = len(self._cache)
    self._index -= 1
    return peeked

